const indices=new WeakMap();
// Explicitly enroll map-owned query arrays. Temporary actor/projectile arrays
// must never rebuild a map index in the middle of a shot.
export function prepareMapRays(meshes,{depth=3,minSources=64,minTriangles=200000}={}){const sources=meshes.filter(mesh=>mesh.userData.staticMapRay);if(sources.length<minSources||sources.reduce((n,mesh)=>n+(mesh.geometry.index?.count||mesh.geometry.attributes.position.count)/3,0)<minTriangles){indices.delete(meshes);return;}indices.set(meshes,new MapRayIndex(meshes,depth));}
export function mapRayIndex(meshes,sync=true){const index=indices.get(meshes);if(index&&sync)index.sync(meshes);return index;}

class MapRayIndex{
 constructor(meshes,depth){this.depth=depth;this.point=new T.Vector3();this.stack=[];this.hits=[];this.build(meshes);}
 build(meshes){this.array=meshes;this.hint=null;this.members=meshes.slice();this.sources=[];this.other=[];this.orders=new Map();this.leaves=[];this.bytes=0;
  for(let order=0;order<meshes.length;order++){const mesh=meshes[order];if(!this.orders.has(mesh))this.orders.set(mesh,order);if(!mesh.userData.staticMapRay||!mesh.geometry.boundsTree||mesh.geometry.groups.length||Array.isArray(mesh.material)){this.other.push(mesh);continue;}const source={mesh,order,matrix:Float64Array.from(mesh.matrixWorld.elements),leaves:[]};this.sources.push(source);const data=MeshBVH.serialize(mesh.geometry.boundsTree,{cloneBuffers:false});
   // Pinned vendor serialization v1 stores child offsets relative to the
   // parent, and leaf offsets into the shared original indirect/index arrays.
   // Whole contiguous subtrees can therefore share every source vertex/index.
   // CPU-only views avoid render objects, buffer ownership and UUID/game RNG.
   if(data.version!==1){this.sources.pop();this.other.push(mesh);continue;}
   for(const root of data.roots){const u32=new Uint32Array(root),u16=new Uint16Array(root),f32=new Float32Array(root);const split=(at,end,depth)=>{if(depth<this.depth&&u16[at*2+15]!==65535){const right=at+u32[at+6]*8;split(at+8,right,depth+1);split(right,end,depth+1);return;}const buffer=root.slice(at*4,end*4),geometry=Object.create(mesh.geometry);geometry.boundingBox=new T.Box3(new T.Vector3(...f32.subarray(at,at+3)),new T.Vector3(...f32.subarray(at+3,at+6)));geometry.boundingSphere=geometry.boundingBox.getBoundingSphere(new T.Sphere());geometry.boundsTree=MeshBVH.deserialize({...data,roots:[buffer]},geometry,{setIndex:false});const proxy={geometry,material:mesh.material,matrixWorld:mesh.matrixWorld,layers:mesh.layers};proxy.raycast=(ray,hits)=>{const start=hits.length,first=ray.firstHitOnly;proxy.material=mesh.material;if(mesh.material.userData.alphaAt)ray.firstHitOnly=false;try{acceleratedRaycast.call(proxy,ray,hits);}finally{ray.firstHitOnly=first;}for(let i=hits.length-1;i>=start;i--){if(mesh.material.userData.alphaAt&&hits[i].uv&&!mesh.material.userData.alphaAt(hits[i].uv))hits.splice(i,1);else hits[i].object=mesh;}};const leaf={proxy,source,local:geometry.boundingBox,box:geometry.boundingBox.clone().applyMatrix4(mesh.matrixWorld)};source.leaves.push(leaf);this.leaves.push(leaf);this.bytes+=buffer.byteLength;};split(0,u32.length,0);}
  }
  this.rebuildTree();
 }
 rebuildTree(){const build=leaves=>{if(!leaves.length)return null;const box=new T.Box3();for(const leaf of leaves)box.union(leaf.box);if(leaves.length<=4)return{box,leaves};const extent=box.getSize(new T.Vector3()),axis=extent.x>=extent.y&&extent.x>=extent.z?'x':extent.y>=extent.z?'y':'z';leaves.sort((a,b)=>(a.box.min[axis]+a.box.max[axis])-(b.box.min[axis]+b.box.max[axis])||a.source.order-b.source.order);const middle=leaves.length>>1;return{box,left:build(leaves.slice(0,middle)),right:build(leaves.slice(middle))};};this.root=build(this.leaves.slice());}
 sync(meshes){let membership=meshes.length!==this.members.length;if(!membership)for(let i=0;i<meshes.length;i++)if(meshes[i]!==this.members[i]){membership=true;break;}if(membership){this.build(meshes);return;}let changed=false;for(const source of this.sources){const matrix=source.mesh.matrixWorld.elements;let moved=false;for(let i=0;i<16;i++)if(matrix[i]!==source.matrix[i]){moved=true;break;}if(moved){source.matrix.set(matrix);for(const leaf of source.leaves){leaf.proxy.matrixWorld=source.mesh.matrixWorld;leaf.box.copy(leaf.local).applyMatrix4(source.mesh.matrixWorld);}changed=true;}}if(changed)this.rebuildTree();}
 entry(ray,box,far){if(box.containsPoint(ray.ray.origin))return 0;const point=ray.ray.intersectBox(box,this.point);if(!point)return Infinity;const distance=ray.ray.origin.distanceTo(point);return distance<=far?distance:Infinity;}
 closest(ray,excludeBot=null){return this.search(ray,excludeBot,false);}
 any(ray,excludeBot=null){const hint=this.hint;let tested=null;if(hint&&this.array[hint.order]===hint.mesh&&(!excludeBot||hint.mesh.userData.bot!==excludeBot)){this.hits.length=0;ray.intersectObject(hint.mesh,false,this.hits);const blocked=this.hits.length>0;this.hits.length=0;if(blocked)return true;tested=hint.mesh;}this.sync(this.array);const hit=this.search(ray,excludeBot,true,tested);this.hint=hit?{mesh:hit.object,order:this.orders.get(hit.object)}:null;return !!hit;}
 search(ray,excludeBot,stopFirst,skipMesh=null){let best=null,order=Infinity,far=ray.far;const stack=this.stack;stack.length=0;if(this.root)stack.push(this.root);this.tests=0;
  while(stack.length){const node=stack.pop();if(this.entry(ray,node.box,far)===Infinity)continue;if(node.leaves){for(const leaf of node.leaves){if(leaf.source.mesh===skipMesh)continue;if(excludeBot&&leaf.source.mesh.userData.bot===excludeBot)continue;leaf.proxy.layers=leaf.source.mesh.layers;if(this.entry(ray,leaf.box,far)===Infinity)continue;this.hits.length=0;const originalFar=ray.far;ray.far=far;try{ray.intersectObject(leaf.proxy,false,this.hits);}finally{ray.far=originalFar;}this.tests++;const hit=this.hits[0];if(hit&&stopFirst){this.hits.length=0;return hit;}if(hit&&(!best||hit.distance<far||hit.distance===far&&leaf.source.order<order)){best=hit;far=hit.distance;order=leaf.source.order;}}}else{const a=this.entry(ray,node.left.box,far),b=this.entry(ray,node.right.box,far);if(a<b){if(b!==Infinity)stack.push(node.right);if(a!==Infinity)stack.push(node.left);}else{if(a!==Infinity)stack.push(node.left);if(b!==Infinity)stack.push(node.right);}}}
  for(const mesh of this.other){if(mesh===skipMesh)continue;if(excludeBot&&mesh.userData.bot===excludeBot)continue;this.hits.length=0;const originalFar=ray.far;ray.far=far;try{ray.intersectObject(mesh,false,this.hits);}finally{ray.far=originalFar;}const hit=this.hits[0],rank=this.orders.get(mesh);if(hit&&stopFirst){this.hits.length=0;return hit;}if(hit&&(!best||hit.distance<far||hit.distance===far&&rank<order)){best=hit;far=hit.distance;order=rank;}}
  this.hits.length=0;return best;
 }
}
